import errno,json,os,shutil,signal,sys,time
from pathlib import Path
START=time.monotonic()
ROOT=Path('/home/qian-qi/heptabao-kv2-ha-convergence-20261106-r1')
def timeout(signum,frame): raise TimeoutError()
signal.signal(signal.SIGALRM,timeout)
signal.setitimer(signal.ITIMER_REAL,52)
report={'schema':'heptabao.rog-original-resource-admission-readonly.v1','product_started':False,'filesystem_mutated':False,'source':'source-4bde9-r9','proposed_output':'build-test-4bde9-r10','compiler_processes':[],'observation_gaps':[]}
try:
    mem=dict((line.split(':')[0],int(line.split()[1])) for line in Path('/proc/meminfo').read_text().splitlines() if line.startswith(('MemAvailable:','SwapFree:')))
    entries=list(Path('/proc').iterdir())
    if len(entries)>65536: raise ValueError()
    count=0
    for path in entries:
        if not path.name.isdigit(): continue
        count+=1
        if time.monotonic()-START>=52: raise TimeoutError()
        try:
            with (path/'comm').open() as f: name=f.read(256).strip()
        except OSError as e:
            if e.errno in (errno.ENOENT,errno.ESRCH): continue
            report['observation_gaps'].append({'pid':int(path.name),'errno':e.errno})
            continue
        if name in {'cargo','rustc','rustfmt','rust-lld'}: report['compiler_processes'].append({'pid':int(path.name),'comm':name})
    report.update(observed_proc_entries=count,disk_free_bytes=shutil.disk_usage(ROOT).free,mem_available_kib=mem['MemAvailable'],swap_free_kib=mem['SwapFree'],load_average=list(os.getloadavg()))
    report['source_directory_present']=(ROOT/report['source']).is_dir()
    try:
        info=(ROOT/report['proposed_output']).lstat()
        report['output_absent']=False
        report['existing_output_metadata']={'inode':info.st_ino,'device':info.st_dev,'mode':info.st_mode,'uid':info.st_uid}
    except FileNotFoundError: report['output_absent']=True
    report['original_thresholds']={'disk_free_bytes_at_least':8*1024**3,'mem_available_kib_at_least':12*1024**2,'compiler_names':['cargo','rustc','rustfmt','rust-lld']}
    report['admission_observation_passed']=(not report['compiler_processes'] and not report['observation_gaps'] and report['source_directory_present'] and report['output_absent'] and report['disk_free_bytes']>=8*1024**3 and report['mem_available_kib']>=12*1024**2)
    report['status']='idle_resources_observed' if report['admission_observation_passed'] else 'held'
except BaseException as e:
    report['status']='observation_failed'
    report['failure_type']=type(e).__name__
    report['admission_observation_passed']=False
finally:
    signal.setitimer(signal.ITIMER_REAL,0)
    report['elapsed_seconds']=time.monotonic()-START
    print(json.dumps(report,sort_keys=True))
sys.exit(0 if report['status']!='observation_failed' else 1)
